const LABELS = require('./sidebar-labels');

// Applies the short labels from sidebar-labels.js to autogenerated items.
function relabel(items) {
  return items.map((item) => {
    if (item.type === 'doc' && LABELS[item.id] && !item.label) {
      return { ...item, label: LABELS[item.id] };
    }
    if (item.type === 'category') {
      return { ...item, items: relabel(item.items) };
    }
    return item;
  });
}

module.exports = async function sidebarItemsGenerator({ defaultSidebarItemsGenerator, ...args }) {
  return relabel(await defaultSidebarItemsGenerator(args));
};
